CREATE TABLE sla_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 120), priority text NOT NULL CHECK(priority IN ('LOW','NORMAL','HIGH','URGENT')), first_response_minutes integer NOT NULL CHECK(first_response_minutes>0), resolution_minutes integer NOT NULL CHECK(resolution_minutes>0), is_active boolean NOT NULL DEFAULT true, UNIQUE(organization_id,priority));
CREATE TABLE ticket_sla_clocks (ticket_id uuid PRIMARY KEY REFERENCES tickets(id) ON DELETE CASCADE, organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, policy_id uuid REFERENCES sla_policies(id), first_response_due_at timestamptz, resolution_due_at timestamptz, first_response_at timestamptz, resolved_at timestamptz, breached_at timestamptz);
ALTER TABLE sla_policies ENABLE ROW LEVEL SECURITY; ALTER TABLE ticket_sla_clocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY sla_policies_tenant ON sla_policies USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id());
CREATE POLICY ticket_sla_clocks_tenant ON ticket_sla_clocks USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id());
GRANT SELECT,INSERT,UPDATE,DELETE ON sla_policies,ticket_sla_clocks TO jupiter_app;
